def families():
    out = []
    for split, data in [('train', TRAIN), ('dev', DEV), ('internal_test', INTERNAL_TEST), ('tuning_eval', TUNING_EVAL)]:
        for intent, recipes in data.items():
            for name, op, text in recipes:
                # Manual cross-split audit found this entire DEV construction too
                # close to TRAIN's record family when the same terms were listed.
                # Quarantine the family, not individual wording/number variants.
                if f'{split}.{intent}.{name}' == 'dev.offer.memo':
                    continue
                out.append(dict(id=f'{split}.{intent}.{name}', split=split, intent=intent, op=op, text=text,
                                semanticFamilyId=f'{split}.{intent}.{name}', surfaceTemplateFamilyId=f'{split}.{intent}.{name}'))
    return out
